/** Whether propose may be given now: the stage is PROSPECT. */
export function canPropose(value: OpportunityDTO | null | undefined): boolean {
    return value != null && (value.stage === OpportunityStage.PROSPECT);
}

/** Whether negotiate may be given now: the stage is PROPOSAL. */
export function canNegotiate(value: OpportunityDTO | null | undefined): boolean {
    return value != null && (value.stage === OpportunityStage.PROPOSAL);
}

/** Whether win may be given now: the stage is PROPOSAL or NEGOTIATION. */
export function canWin(value: OpportunityDTO | null | undefined): boolean {
    return value != null && (value.stage === OpportunityStage.PROPOSAL || value.stage === OpportunityStage.NEGOTIATION);
}

/** Whether lose may be given now: the stage is PROSPECT or PROPOSAL or NEGOTIATION. */
export function canLose(value: OpportunityDTO | null | undefined): boolean {
    return value != null && (value.stage === OpportunityStage.PROSPECT || value.stage === OpportunityStage.PROPOSAL || value.stage === OpportunityStage.NEGOTIATION);
}

/** Whether reopen may be given now: the stage is LOST. */
export function canReopen(value: OpportunityDTO | null | undefined): boolean {
    return value != null && (value.stage === OpportunityStage.LOST);
}

/** Whether it may be deleted now: the stage is PROSPECT or LOST. */
export function canDelete(value: OpportunityDTO | null | undefined): boolean {
    return value != null && (value.stage === OpportunityStage.PROSPECT || value.stage === OpportunityStage.LOST);
}

